/// Raven `G_RunFrame`.
///
/// Source: `oracle/codemp/game/g_main.c:3582-4102`
pub fn G_RunFrame(ctx: &mut GameContext, levelTime: c_int) {
    unsafe {
        if ctx.world.cvars.g_gametype.integer == GT_SIEGE
            && ctx.world.cvars.g_siegeRespawn.integer != 0
            && ctx.world.globals.g_siegeRespawnCheck < ctx.world.level.time
        {
            // check for a respawn wave
            let mut i: c_int = 0;
            while (i as usize) < MAX_CLIENTS {
                let id = EntityId(i as u32);
                let inuse = ctx.world.entity(id).inuse;
                // FLAG(pool-client): read the entity's `gclient_t*` value and
                // deref it raw (recipe 2b); `client_ptr` is a copied pointer held
                // across `respawn(ctx, …)`, the sanctioned pool-client pattern.
                let client_ptr = ctx.world.entity(id).client;
                if inuse != qfalse
                    && !client_ptr.is_null()
                    && (*client_ptr).tempSpectate > ctx.world.level.time
                    && (*client_ptr).sess.sessionTeam != TEAM_SPECTATOR
                {
                    respawn(ctx, id);
                    (*client_ptr).tempSpectate = 0;
                }
                i += 1;
            }

            ctx.world.globals.g_siegeRespawnCheck =
                ctx.world.level.time + ctx.world.cvars.g_siegeRespawn.integer * 1000;
        }

        if ctx.world.globals.gDoSlowMoDuel != qfalse {
            if ctx.world.level.restarted != qfalse {
                let mut buf: [c_char; 128] = [0; 128];
                trap::Cvar_VariableStringBuffer(
                    ctx.engine,
                    mp_abi::game::syscalls::G_CVAR_VARIABLE_STRING_BUFFER::GCvarVariableStringBufferArgs::new(
                        cstr("timescale"),
                        buf.as_mut_ptr(),
                        buf.len() as c_int,
                    ),
                );
                let t_fval = atof(buf.as_ptr()) as f32;
                trap::Cvar_Set(
                    ctx.engine,
                    mp_abi::game::syscalls::G_CVAR_SET::GCvarSetArgs::new(
                        cstr("timescale"),
                        cstr("1"),
                    ),
                );
                if t_fval == 1.0f32 {
                    ctx.world.globals.gDoSlowMoDuel = qfalse;
                }
            } else {
                // difference in time between when the slow motion was initiated and now
                let time_dif = (ctx.world.level.time - ctx.world.globals.gSlowMoDuelTime) as f32;

                if time_dif < 150.0 {
                    trap::Cvar_Set(
                        ctx.engine,
                        mp_abi::game::syscalls::G_CVAR_SET::GCvarSetArgs::new(
                            cstr("timescale"),
                            cstr("0.1f"),
                        ),
                    );
                } else if time_dif < 1150.0 {
                    let mut use_dif = time_dif / 1000.0; // scale from 0.1 up to 1
                    if use_dif < 0.1 {
                        use_dif = 0.1;
                    }
                    if use_dif > 1.0 {
                        use_dif = 1.0;
                    }
                    trap::Cvar_Set(
                        ctx.engine,
                        mp_abi::game::syscalls::G_CVAR_SET::GCvarSetArgs::new(
                            cstr("timescale"),
                            // `va("%f", useDif)` formats with 6 fixed decimals.
                            cstr(&format!("{:.6}", use_dif)),
                        ),
                    );
                } else {
                    let mut buf: [c_char; 128] = [0; 128];
                    trap::Cvar_VariableStringBuffer(
                        ctx.engine,
                        mp_abi::game::syscalls::G_CVAR_VARIABLE_STRING_BUFFER::GCvarVariableStringBufferArgs::new(
                            cstr("timescale"),
                            buf.as_mut_ptr(),
                            buf.len() as c_int,
                        ),
                    );
                    let t_fval = atof(buf.as_ptr()) as f32;
                    trap::Cvar_Set(
                        ctx.engine,
                        mp_abi::game::syscalls::G_CVAR_SET::GCvarSetArgs::new(
                            cstr("timescale"),
                            cstr("1"),
                        ),
                    );
                    if time_dif > 1500.0 && t_fval == 1.0f32 {
                        ctx.world.globals.gDoSlowMoDuel = qfalse;
                    }
                }
            }
        }

        // if we are waiting for the level to restart, do nothing
        if ctx.world.level.restarted != qfalse {
            return;
        }

        ctx.world.level.framenum += 1;
        ctx.world.level.previousTime = ctx.world.level.time;
        ctx.world.level.time = levelTime;
        let _msec = ctx.world.level.time - ctx.world.level.previousTime;

        if ctx.world.cvars.g_allowNPC.integer != 0 {
            NAV_CheckCalcPaths(ctx);
        }

        AI_UpdateGroups(ctx);

        if ctx.world.cvars.g_allowNPC.integer != 0 {
            if ctx.world.cvars.d_altRoutes.integer != 0 {
                trap::Nav_CheckAllFailedEdges(
                    ctx.engine,
                    mp_abi::game::syscalls::G_NAV_CHECKALLFAILEDEDGES::GNavCheckallfailededgesArgs::new(),
                );
            }
            trap::Nav_ClearCheckedNodes(
                ctx.engine,
                mp_abi::game::syscalls::G_NAV_CLEARCHECKEDNODES::GNavClearcheckednodesArgs::new(),
            );

            // remember last waypoint, clear current one
            let mut i: c_int = 0;
            while i < ctx.world.level.num_entities {
                let id = EntityId(i as u32);
                if ctx.world.entity(id).inuse == qfalse {
                    i += 1;
                    continue;
                }

                if ctx.world.entity(id).waypoint != WAYPOINT_NONE
                    && ctx.world.entity(id).noWaypointTime < ctx.world.level.time
                {
                    let wp = ctx.world.entity(id).waypoint;
                    ctx.world.entity_mut(id).lastWaypoint = wp;
                    ctx.world.entity_mut(id).waypoint = WAYPOINT_NONE;
                }
                if ctx.world.cvars.d_altRoutes.integer != 0 {
                    let ent_ptr = ctx.entity_mut(id) as *mut gentity_t;
                    trap::Nav_CheckFailedNodes(
                        ctx.engine,
                        mp_abi::game::syscalls::G_NAV_CHECKFAILEDNODES::GNavCheckfailednodesArgs::new(ent_ptr.cast()),
                    );
                }
                i += 1;
            }

            // Look to clear out old events
            ClearPlayerAlertEvents(ctx);
        }

        ctx.world.globals.g_TimeSinceLastFrame =
            ctx.world.level.time - ctx.world.globals.g_LastFrameTime;

        // get any cvar changes
        G_UpdateCvars(ctx);

        //
        // go through all allocated objects
        //
        // FLAG(2c-defer): this `MAX_GENTITIES`-wide dispatch loop walks arbitrary
        // entities (i >= MAX_CLIENTS are NPCs carrying BG_Alloc'd POOL clients,
        // not `clients[i]` — recipe 2b), holds the raw `ent`/`client` across
        // dozens of interleaved `ctx` subsystem calls (G_RunMissile/G_Damage/
        // G_SetAnim/WP_*), and mutates entity + pool-client state in lockstep.
        // Left on the Stage-1 raw-pointer body for a dedicated referee-gated
        // shard; the surrounding G_RunFrame sub-loops are converted above/below.
        let mut i: c_int = 0;
        while i < ctx.world.level.num_entities {
            let ent = ctx.world.g_entities.as_mut_ptr().add(i as usize);
            if (*ent).inuse == qfalse {
                i += 1;
                continue;
            }

            // clear events that are too old
            if ctx.world.level.time - (*ent).eventTime > EVENT_VALID_MSEC {
                if (*ent).s.event != 0 {
                    (*ent).s.event = 0; // &= EV_EVENT_BITS;
                    if !(*ent).client.is_null() {
                        (*((*ent).client)).ps.externalEvent = 0;
                    }
                }
                if (*ent).freeAfterEvent != qfalse {
                    // tempEntities or dropped items completely go away after their event
                    if (*ent).s.eFlags & EF_SOUNDTRACKER != 0 {
                        // don't trigger the event again..
                        (*ent).s.event = 0;
                        (*ent).s.eventParm = 0;
                        (*ent).s.eType = 0;
                        (*ent).eventTime = 0;
                    } else {
                        G_FreeEntity(ctx, ctx.entity_id_of(ent));
                        i += 1;
                        continue;
                    }
                } else if (*ent).unlinkAfterEvent != qfalse {
                    // items that will respawn will hide themselves after their pickup event
                    (*ent).unlinkAfterEvent = qfalse;
                    trap::UnlinkEntity(
                        ctx.engine,
                        mp_abi::game::syscalls::G_UNLINKENTITY::GUnlinkentityArgs::new(ent.cast()),
                    );
                }
            }

            // temporary entities don't think
            if (*ent).freeAfterEvent != qfalse {
                i += 1;
                continue;
            }

            if (*ent).r.linked == qfalse && (*ent).neverFree != qfalse {
                i += 1;
                continue;
            }

            if (*ent).s.eType == entityType_t::ET_MISSILE as c_int {
                G_RunMissile(ctx, ctx.entity_id_of(ent).unwrap());
                i += 1;
                continue;
            }

            if (*ent).s.eType == entityType_t::ET_ITEM as c_int || (*ent).physicsObject != qfalse {
                G_RunItem(ctx, ctx.entity_id_of(ent).unwrap());
                i += 1;
                continue;
            }

            if (*ent).s.eType == entityType_t::ET_MOVER as c_int {
                G_RunMover(ctx, ctx.entity_id_of(ent).unwrap());
                i += 1;
                continue;
            }

            if (i as usize) < MAX_CLIENTS {
                G_CheckClientTimeouts(ctx, ctx.entity_id_of(ent).unwrap());

                let client = (*ent).client;
                if (*client).inSpaceIndex != 0 && (*client).inSpaceIndex != ENTITYNUM_NONE {
                    // we're in space, check for suffocating and for exiting
                    let spacetrigger = ctx
                        .world
                        .g_entities
                        .as_mut_ptr()
                        .add((*client).inSpaceIndex as usize);

                    if (*spacetrigger).inuse == qfalse
                        || G_PointInBounds(
                            (*client).ps.origin,
                            (*spacetrigger).r.absmin,
                            (*spacetrigger).r.absmax,
                        ) == qfalse
                    {
                        // no longer in space then I suppose
                        (*client).inSpaceIndex = 0;
                    } else {
                        // check for suffocation
                        if (*client).inSpaceSuffocation < ctx.world.level.time {
                            // suffocate!
                            if (*ent).health > 0 && (*ent).takedamage != qfalse {
                                // if they're still alive..
                                let dmg = ctx.world.bg_state.rng.Q_irand(50, 70);
                                let targ_id = ctx.entity_id_of(ent);
                                let inflictor_id = ctx.entity_id_of(spacetrigger);
                                let attacker_id = ctx.entity_id_of(spacetrigger);
                                G_Damage(
                                    ctx,
                                    targ_id,
                                    inflictor_id,
                                    attacker_id,
                                    None,
                                    (*client).ps.origin,
                                    dmg,
                                    DAMAGE_NO_ARMOR,
                                    MOD_SUICIDE as c_int,
                                );

                                if (*ent).health > 0 {
                                    // play the choking sound
                                    let n = ctx.world.bg_state.rng.Q_irand(1, 3);
                                    let snd =
                                        G_SoundIndex(cstr(&format!("*choke{}.wav", n)).as_ptr());
                                    let ent_id = ctx.entity_id_of(ent).unwrap();
                                    G_EntitySound(ctx, ent_id, CHAN_VOICE, snd);

                                    // make them grasp their throat
                                    (*client).ps.forceHandExtend = HANDEXTEND_CHOKE as c_int;
                                    (*client).ps.forceHandExtendTime = ctx.world.level.time + 2000;
                                }
                            }

                            (*client).inSpaceSuffocation =
                                ctx.world.level.time + ctx.world.bg_state.rng.Q_irand(100, 200);
                        }
                    }
                }

                if (*client).isHacking != 0 {
                    // hacking checks
                    let hacked = ctx
                        .world
                        .g_entities
                        .as_mut_ptr()
                        .add((*client).isHacking as usize);
                    let mut ang_dif: vec3_t = [0.0; 3];

                    crate::q_math::_VectorSubtract(
                        (*client).ps.viewangles,
                        (*client).hackingAngles,
                        &mut ang_dif,
                    );

                    // keep him in the "use" anim
                    if (*client).ps.torsoAnim != BOTH_CONSOLE1 as c_int {
                        let ent_id = ctx.entity_id_of(ent).unwrap();
                        G_SetAnim(
                            ctx,
                            ent_id,
                            std::ptr::null_mut(),
                            SETANIM_TORSO,
                            BOTH_CONSOLE1 as c_int,
                            SETANIM_FLAG_OVERRIDE | SETANIM_FLAG_HOLD,
                            0,
                        );
                    } else {
                        (*client).ps.torsoTimer = 500;
                    }
                    (*client).ps.weaponTime = (*client).ps.torsoTimer;

                    if (*client).pers.cmd.buttons & BUTTON_USE == 0 {
                        // have to keep holding use
                        (*client).isHacking = 0;
                        (*client).ps.hackingTime = 0;
                    } else if hacked.is_null() || (*hacked).inuse == qfalse {
                        // shouldn't happen, but safety first
                        (*client).isHacking = 0;
                        (*client).ps.hackingTime = 0;
                    } else if G_PointInBounds(
                        (*client).ps.origin,
                        (*hacked).r.absmin,
                        (*hacked).r.absmax,
                    ) == qfalse
                    {
                        // they stepped outside the thing they're hacking, so reset hacking time
                        (*client).isHacking = 0;
                        (*client).ps.hackingTime = 0;
                    } else if VectorLength(ang_dif) > 10.0f32 {
                        // must remain facing generally the same angle as when we start
                        (*client).isHacking = 0;
                        (*client).ps.hackingTime = 0;
                    }
                }

                // JETPACK_DEFUEL_RATE ~= 200, JETPACK_REFUEL_RATE ~= 150 (g_main.c:3895-3896 local #defines)
                if (*client).jetPackOn != qfalse {
                    // using jetpack, drain fuel
                    if (*client).jetPackDebReduce < ctx.world.level.time {
                        if (*client).pers.cmd.upmove > 0 {
                            // take more if they're thrusting
                            (*client).ps.jetpackFuel -= 2;
                        } else {
                            (*client).ps.jetpackFuel -= 1;
                        }

                        if (*client).ps.jetpackFuel <= 0 {
                            // turn it off
                            (*client).ps.jetpackFuel = 0;
                            Jetpack_Off(&mut *ent);
                        }
                        (*client).jetPackDebReduce = ctx.world.level.time + 200;
                    }
                } else if (*client).ps.jetpackFuel < 100 {
                    // recharge jetpack
                    if (*client).jetPackDebRecharge < ctx.world.level.time {
                        (*client).ps.jetpackFuel += 1;
                        (*client).jetPackDebRecharge = ctx.world.level.time + 150;
                    }
                }

                // CLOAK_DEFUEL_RATE ~= 200, CLOAK_REFUEL_RATE ~= 150 (g_main.c:3927-3928 local #defines)
                if (*client).ps.powerups[PW_CLOAKED as usize] != 0 {
                    // using cloak, drain battery
                    if (*client).cloakDebReduce < ctx.world.level.time {
                        (*client).ps.cloakFuel -= 1;

                        if (*client).ps.cloakFuel <= 0 {
                            // turn it off
                            (*client).ps.cloakFuel = 0;
                            Jedi_Decloak(ctx, ctx.entity_id_of(ent));
                        }
                        (*client).cloakDebReduce = ctx.world.level.time + 200;
                    }
                } else if (*client).ps.cloakFuel < 100 {
                    // recharge cloak
                    if (*client).cloakDebRecharge < ctx.world.level.time {
                        (*client).ps.cloakFuel += 1;
                        (*client).cloakDebRecharge = ctx.world.level.time + 150;
                    }
                }

                if ctx.world.cvars.g_gametype.integer == GT_SIEGE
                    && (*client).siegeClass != -1
                    && ctx.world.bg_state.bgSiegeClasses[(*client).siegeClass as usize].classflags
                        & (1 << (CFL_STATVIEWER as c_int))
                        != 0
                {
                    // see if it's time to send this guy an update of extended info
                    if (*client).siegeEDataSend < ctx.world.level.time {
                        G_SiegeClientExData(ctx, ctx.entity_id_of(ent).unwrap());
                        (*client).siegeEDataSend = ctx.world.level.time + 1000; // once every sec seems ok
                    }
                }

                if ctx.world.level.intermissiontime == 0
                    && (*client).ps.pm_flags & PMF_FOLLOW == 0
                    && (*client).sess.sessionTeam != TEAM_SPECTATOR
                {
                    WP_ForcePowersUpdate(ctx, ctx.entity_id_of(ent), &mut (*client).pers.cmd);
                    WP_SaberPositionUpdate(ctx, ctx.entity_id_of(ent), &mut (*client).pers.cmd);
                    let ent_id = ctx.entity_id_of(ent).unwrap();
                    WP_SaberStartMissileBlockCheck(ctx, ent_id, &mut (*client).pers.cmd);
                }

                if ctx.world.cvars.g_allowNPC.integer != 0 {
                    // This was originally intended to only be done for client 0.
                    // Make sure it doesn't slow things down too much with lots of clients in game.
                    NAV_FindPlayerWaypoint(ctx, i);
                }

                trap::ICARUS_MaintainTaskManager(
                    ctx.engine,
                    mp_abi::game::syscalls::G_ICARUS_MAINTAINTASKMANAGER::GIcarusMaintaintaskmanagerArgs::new((*ent).s.number),
                );

                G_RunClient(ctx, ctx.entity_id_of(ent).unwrap());
                i += 1;
                continue;
            } else if (*ent).s.eType == entityType_t::ET_NPC as c_int {
                let client = (*ent).client;
                // turn off any expired powerups
                let mut j: usize = 0;
                while j < MAX_POWERUPS {
                    if (*client).ps.powerups[j] < ctx.world.level.time {
                        (*client).ps.powerups[j] = 0;
                    }
                    j += 1;
                }

                WP_ForcePowersUpdate(ctx, ctx.entity_id_of(ent), &mut (*client).pers.cmd);
                WP_SaberPositionUpdate(ctx, ctx.entity_id_of(ent), &mut (*client).pers.cmd);
                let ent_id = ctx.entity_id_of(ent).unwrap();
                WP_SaberStartMissileBlockCheck(ctx, ent_id, &mut (*client).pers.cmd);
            }

            G_RunThink(ctx, ctx.entity_id_of(ent).unwrap());

            if ctx.world.cvars.g_allowNPC.integer != 0 {
                ClearNPCGlobals(ctx);
            }
            i += 1;
        }

        SiegeCheckTimers(ctx);

        trap::ROFF_UpdateEntities(
            ctx.engine,
            mp_abi::game::syscalls::G_ROFF_UPDATE_ENTITIES::GRoffUpdateEntitiesArgs::new(),
        );

        // perform final fixups on the players
        let mut i: c_int = 0;
        while i < ctx.world.level.maxclients {
            let id = EntityId(i as u32);
            if ctx.world.entity(id).inuse != qfalse {
                ClientEndFrame(ctx, id);
            }
            i += 1;
        }

        // see if it is time to do a tournement restart
        CheckTournament(ctx);

        // see if it is time to end the level
        CheckExitRules(ctx);

        // update to team status?
        CheckTeamStatus(ctx);

        // cancel vote if timed out
        CheckVote(ctx);

        // check team votes
        CheckTeamVote(ctx, TEAM_RED as c_int);
        CheckTeamVote(ctx, TEAM_BLUE as c_int);

        // for tracking changes
        CheckCvars(ctx);

        if ctx.world.cvars.g_listEntity.integer != 0 {
            let mut i: c_int = 0;
            while (i as usize) < MAX_GENTITIES {
                let classname = ctx.world.g_entities[i as usize].classname;
                // §19: oracle passes a possibly-NULL classname to %s (UB); we
                // print "" for unused slots.
                let name = if classname.is_null() {
                    String::new()
                } else {
                    cstr_to_str(classname)
                };
                G_Printf(ctx, cstr(&format!("{:4}: {}\n", i, name)).as_ptr());
                i += 1;
            }
            trap::Cvar_Set(
                ctx.engine,
                mp_abi::game::syscalls::G_CVAR_SET::GCvarSetArgs::new(
                    cstr("g_listEntity"),
                    cstr("0"),
                ),
            );
        }

        // At the end of the frame, send out the ghoul2 kill queue, if there is one
        G_SendG2KillQueue(ctx);

        if ctx.world.globals.gQueueScoreMessage != qfalse {
            if ctx.world.globals.gQueueScoreMessageTime < ctx.world.level.time {
                SendScoreboardMessageToAllClients(ctx);

                ctx.world.globals.gQueueScoreMessageTime = 0;
                ctx.world.globals.gQueueScoreMessage = qfalse;
            }
        }

        ctx.world.globals.g_LastFrameTime = ctx.world.level.time;
    }
}

/// Raven `G_GetStringEdString`.
///
/// Source: `oracle/codemp/game/g_main.c:4104-4120`
pub fn G_GetStringEdString(
    ctx: &mut GameContext,
    refSection: *mut c_char,
    refName: *mut c_char,
) -> *const c_char {
    // Well, it would've been lovely doing it the above way, but it would mean
    // mixing languages for the client depending on what the server is. So
    // we'll mark this as a stringed reference with @@@ and send the refname
    // to the client, and when it goes to print it will get scanned for the
    // stringed reference indication and dealt with properly.
    //
    // Raven's `static char text[1024]` is a single reused rotating buffer;
    // ported as an owned, leaked `'static` allocation per call instead.
    unsafe {
        let name = cstr_to_str(refName);
        let text = format!("@@@{}", name);
        let leaked: &'static CString = Box::leak(Box::new(cstr(&text)));
        leaked.as_ptr()
    }
}
